verify.test:
import assert from 'node:assert';
assert.strictEqual(isPalindrome('Racecar'), true);
assert.strictEqual(isPalindrome('A man, a plan, a canal: Panama'), true);
assert.strictEqual(isPalindrome('hello'), false);
assert.strictEqual(isPalindrome(''), true);

import assert from 'node:assert';
assert.strictEqual(sum([1,2,3]), 6);
assert.strictEqual(sum([]), 0);
assert.strictEqual(sum([-1, 1.5]), 0.5);

import assert from 'node:assert';
assert.strictEqual(isValidEmail('a.b+tag@example.co.in'), true);
assert.strictEqual(isValidEmail('user@site.com'), true);
assert.strictEqual(isValidEmail('no-at-sign.com'), false);
assert.strictEqual(isValidEmail('a@@b.com'), false);
assert.strictEqual(isValidEmail('a b@c.com'), false);
assert.strictEqual(isValidEmail('a@localhost'), false);

import assert from 'node:assert';
const c = createLRU(2);
c.put('a', 1); c.put('b', 2);
assert.strictEqual(c.get('a'), 1);
c.put('c', 3);
assert.strictEqual(c.get('b'), undefined);
assert.strictEqual(c.get('a'), 1);
assert.strictEqual(c.get('c'), 3);
c.put('a', 10); c.put('d', 4);
assert.strictEqual(c.get('c'), undefined);
assert.strictEqual(c.get('a'), 10);

import assert from 'node:assert';
assert.deepStrictEqual(fizzBuzz(5), [1, 2, 'Fizz', 4, 'Buzz']);
assert.strictEqual(fizzBuzz(15)[14], 'FizzBuzz');
assert.strictEqual(fizzBuzz(15).length, 15);
